let giftWrapStyle='sage',localDialogue=null,experienceSession=null,photoOptions={frame:'sage',pose:'wave',preview:null},photoBusy=false;
let journeyBusy=false,nightDay=null,homeJourney=null,audioContext=null,pendingImport=null,clockAccumulator=0;
const escapeHTML=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
