function closeMapPanel(){mapPanel=null;renderMapPanel();hud();if(mapPanelOpener?.isConnected)mapPanelOpener.focus({preventScroll:true});else focusMap();}
function toggleMapPanel(button){if(mapPanel===button.dataset.id){closeMapPanel();return;}mapPanelOpener=button;mapPanel=button.dataset.id;world?.stopWalking();walkPad?.cancel();renderMapPanel();hud();$('#map-panel [data-action="close-map-panel"]')?.focus({preventScroll:true});}
function renderMapPanel(){const root=$('#map-panel');if(!root)return;$('.map-stage').classList.toggle('panel-open',!!mapPanel);if(!mapPanel){root.innerHTML='';return;}const mall=E.mallOf(s),plan=E.planFor(s),trail=E.mapTrail(s),all=[...new Set(mall.sections.flatMap(d=>d.stores))];let body='';if(mapPanel==='shops')body=`<div class="shop-finder"><label for="shop-finder-query">Find a shop</label><input id="shop-finder-query" type="search" placeholder="Shop name or product type" value="${escapeHTML(shopQuery)}"><div class="shop-finder-filters"><select id="shop-finder-floor" aria-label="Shop floor"><option value="all">Every floor</option>${plan.levels.map((name,i)=>`<option value="${i}" ${shopFloor===String(i)?'selected':''}>${escapeHTML(name)}</option>`).join('')}</select><select id="shop-finder-availability" aria-label="Shop availability"><option value="ready" ${shopAvailability==='ready'?'selected':''}>Stocked & services</option><option value="all" ${shopAvailability==='all'?'selected':''}>All locations</option></select></div><div id="shop-finder-results">${shopRows(s,{E,esc:escapeHTML},shopQuery,shopFloor,shopAvailability)}</div></div>`;else if(mapPanel==='services')body=momentHTML()+`<h3 class="drawer-subtitle">Meet the regulars</h3><div class="local-list">${E.LOCALS.map(n=>`<button data-action="local-visit" data-id="${n.id}"><i style="background:${n.color}">${n.name[0]}</i><span><strong>${n.name}</strong><small>${n.role}</small></span><b>↗</b></button>`).join('')}</div>${world?.layout.environment?.seating.length?'<h3 class="drawer-subtitle">A seat nearby</h3><div class="stop-grid">'+world.layout.environment.seating.slice().sort((a,b)=>Math.hypot(a.approach.x-world.avatar.x,a.approach.y-world.avatar.y)-Math.hypot(b.approach.x-world.avatar.x,b.approach.y-world.avatar.y)).slice(0,2).map(f=>'<button data-action="public-seat" data-id="'+f.id+'"><span>🪑</span><strong>Walk to a garden bench</strong></button>').join('')+'</div>':''}${world?.layout.environment?.fixtures.some(f=>f.venue)?'<h3 class="drawer-subtitle">Counters along the arcade</h3><div class="stop-grid">'+world.layout.environment.fixtures.filter(f=>f.venue).sort((a,b)=>Math.hypot(a.approach.x-world.avatar.x,a.approach.y-world.avatar.y)-Math.hypot(b.approach.x-world.avatar.x,b.approach.y-world.avatar.y)).slice(0,4).map(f=>'<button data-action="public-stop" data-id="'+f.id+'"><span>'+({coffee:'☕',photo:'📷',flowers:'💐',popup:'🎪'}[f.venue])+'</span><strong>'+({coffee:'Coffee kiosk',photo:'Outfit photo spot',flowers:'Flower cart',popup:'Pop-up counter'}[f.venue])+'</strong></button>').join('')+'</div>':''}<h3 class="drawer-subtitle">Lend a little hand</h3><div class="stop-grid"><button data-action="neighborhood-route" data-id="notice"><span>📌</span><strong>Community notices</strong></button><button data-action="neighborhood-route" data-id="property"><span>🔎</span><strong>Lost-property desk</strong></button></div><h3 class="drawer-subtitle">Make a little detour</h3><div class="stop-grid">${E.VENUES.map(v=>`<button data-action="venue" data-id="${v.id}"><span>${v.emoji}</span><strong>${v.name}</strong></button>`).join('')}</div>`;else if(mapPanel==='story')body=missionCard(E.activeMission(s))+`<button class="button secondary wide" data-action="view" data-id="missions">All chapters & daily goals</button>`;else body=`<p>Explore the anchor courts and landmarks to complete this mall’s discovery trail.</p><div class="trail-progress"><strong>${trail.count} / ${trail.target} landmarks found</strong><small>Reward: 100 XP + $50 game money</small></div>${plan.anchors.map((a,i)=>`<button class="map-landmark-row" data-action="landmark-visit" data-id="${mall.id}:${i}"><span>${s.landmarkStamps.some(x=>x.startsWith(mall.id+':'+i+':'))?'✓':'○'}</span>${a.name}<b>↗</b></button>`).join('')}<button class="button orange wide" data-action="trail-claim" data-id="${mall.id}" ${!trail.ready||trail.claimed?'disabled':''}>${trail.claimed?'Trail completed ✓':'Collect discovery reward'}</button><details class="map-source"><summary>Map reference & accuracy</summary><p>${plan.note}</p><p>The 3D courtyard is an original playable arrangement inspired by the center’s architecture and activities. Tenant locations and interiors are curated game scenes. The optional 2D guide is schematic. Neither is a current floor plan or a navigation aid.</p><a href="${plan.source}" target="_blank" rel="noopener noreferrer">Open the official center map ↗</a></details>`;
 if(mapPanel==='guide')body='<button class="button orange wide" data-action="center-map">Open the complete center map ↗</button>'+body;root.innerHTML=`<aside class="map-drawer" aria-label="${{shops:'Mall shops',services:'Services and activities',story:'Current story',guide:'Mall guide'}[mapPanel]}"><header><h2>${{shops:'Find your next stop',services:'Take a little break',story:'Your shopping story',guide:'Discover the whole mall'}[mapPanel]}</h2><button data-action="close-map-panel" aria-label="Close map panel">×</button></header><div class="map-drawer-body">${body}</div></aside>`;icons(root);
}
function landmarkModal(id){const p=E.planFor(s),index=Number(id.split(':')[1]),a=p.anchors[index];if(!a)return;const found=s.landmarkStamps.includes(id+':'+(s.floor||0));modal(a.name,p.name+' · '+p.levels[s.floor||0],`<div class="success-body"><div class="success-icon">📍</div><h3>A place worth knowing.</h3><p>${a.name} is a real landmark or anchor shown in the center references. Explore it to add a stamp to your mall trail.</p><button class="button orange wide" data-action="landmark-stamp" data-id="${id}" ${found?'disabled':''}>${found?'Stamp collected ✓':'Explore · 3 min · +12 XP'}</button><button class="text-button" data-action="close">Continue walking</button><p class="catalog-note">${p.note}</p><a href="${p.source}" target="_blank" rel="noopener noreferrer">Official map reference ↗</a></div>`,{small:true});}
function momentHTML(){const g=E.momentStatus(s),steps=Number(g.windows>=2)+Number(g.talks>=1)+Number(g.activities>=1);return `<details class="moment-card"><summary><small>TODAY’S MALL MOMENT</small><strong>Browse. Meet. Make a memory.</strong><span>${g.claimed?'Collected ✓':steps+' / 3 steps · 60 XP + $35'}<b>⌄</b></span></summary><div class="moment-checks"><span class="${g.windows>=2?'done':''}">${g.windows>=2?'✓':'○'} Read ${Math.min(2,g.windows)}/2 window labels</span><span class="${g.talks?'done':''}">${g.talks?'✓':'○'} Say hello to a regular</span><span class="${g.activities?'done':''}">${g.activities?'✓':'○'} Enjoy a center activity</span></div><button class="button ${g.ready?'orange':'secondary'} wide" data-action="moment-claim" ${!g.ready||g.claimed?'disabled':''}>${g.claimed?'Today’s memory collected ✓':'Collect 60 XP + $35'}</button></details>`;}
function windowModal(id){const st=E.storeById(id);if(!st)return;const items=windowSelection(E.PRODUCTS,id,s.day);modal(st.name+' · Window shopping',E.mallOf(s).name+' · '+E.planFor(s).levels[s.floor||0]+' · Clock paused',`<div class="window-intro"><span>THE WINDOW EDIT · DAY ${s.day}</span><h3>Something catch your eye?</h3><p>A real-product window edit to get you started. Read a label, save a favorite, or step inside for all ${st.count} items.</p></div><div class="window-grid">${items.map(p=>`<article class="window-product"><div class="product-art">${picture(p)}</div><div><small>${escapeHTML(p.brand)}</small><h3>${escapeHTML(p.name)}</h3><strong>${E.money(E.price(s,p))}</strong>${p.reference?`<p>Model / reference: ${escapeHTML(p.reference)}</p>`:''}${s.windowVisits.includes(`${s.day}:${s.mallId}:${p.id}`)?`<p class="window-label">${escapeHTML(p.material)}</p>`:''}<a class="real-item-link" href="${p.source}" target="_blank" rel="noopener noreferrer">${sourceLabel(p)}</a><button class="button secondary wide" data-action="window-read" data-id="${p.id}">${s.windowVisits.includes(`${s.day}:${s.mallId}:${p.id}`)?'Label read ✓':'Read label · 3 min'}</button><button class="text-button" data-action="wish" data-id="${p.id}" aria-label="Save ${escapeHTML(p.name)} to wishlist">♡ Save for later</button></div></article>`).join('')}</div><div class="window-footer"><button class="button orange" data-action="visit" data-id="${id}">Step inside ${escapeHTML(st.name)} · ${st.count} items ↗</button><button class="button secondary" data-action="close">Keep exploring</button><p>Real product identities. Game prices and stock. Linked references may describe an archive model or a brand collection.</p></div>`,{type:'window'});}
function localModal(id){renderLocal(id);}
function routeToWindow(id){if(E.isServiceStore(E.storeById(id))){goStore(id);return;}const mall=E.mallForStore(s,id),floor=E.storeFloor(mall,id);if(s.mallId!==mall.id||(s.floor||0)!==floor){pendingWindow=id;goStore(id);return;}closeModal();mapPanel=null;renderMapPanel();s.paused=false;updateMapOverlay();focusMap();world.goToWindow(id);}
async function toggleFullscreen(){if(view==='menu')showView('mall');const doc=document,active=doc.fullscreenElement||doc.webkitFullscreenElement;if(active||document.body.classList.contains('expanded-play')){document.body.classList.remove('expanded-play');if(active){const exit=doc.exitFullscreen||doc.webkitExitFullscreen;if(exit)try{await exit.call(doc);}catch{}}syncPlayContext();world?.resize();return;}document.body.classList.add('expanded-play');const request=doc.documentElement.requestFullscreen||doc.documentElement.webkitRequestFullscreen;if(request){try{await request.call(doc.documentElement);}catch{toast('Expanded play is on. This browser did not allow native fullscreen.');}}else toast('Expanded play is on. Native fullscreen is unavailable in this browser.');world?.resize();syncPlayContext();}

function updateMapOverlay(){const root=$('#map-overlay');if(!root)return;root.innerHTML=s.minutes>=E.CLOSE?`<div class="map-overlay"><div><strong>That’s the day.</strong><p>The mall is closed. Your bed is calling.</p><button class="button orange" data-action="end-day">Head home & sleep</button></div></div>`:s.paused?`<div class="map-overlay"><div><strong>A little pause.</strong><p>Your clock and needs are paused.</p><button class="button" data-action="pause">Resume the day ▶</button></div></div>`:'';}
function modal(title,subtitle,body,{small=false,type='detail',footer=''}={}){
 if(!$('#modal-root').children.length)lastFocus=document.activeElement;walkPad?.cancel();world?.clearInput();modalType=type;document.body.style.overflow='hidden';setGameInert(true);
 $('#modal-root').innerHTML=`<div class="modal-overlay"><section class="modal ${small?'small':''}" role="dialog" aria-modal="true" aria-label="${escapeHTML(title)}"><header class="modal-header"><div><h2>${escapeHTML(title)}</h2>${subtitle?`<small>${subtitle}</small>`:''}</div><button class="close-button" data-action="close" aria-label="Close dialog">${icon('close')}</button></header>${body}${footer}</section></div>`;icons($('#modal-root'));$('.close-button').focus({preventScroll:true});hud();
}
function closeModal(){if(modalType==='experience')experienceSession=null;const wasOpen=!!$('#modal-root').children.length;document.body.style.overflow='';$('#modal-root').innerHTML='';modalType=null;selectedProduct=null;if(!journeyBusy&&!activityBusy){setGameInert(false);}if(wasOpen&&lastFocus?.isConnected)lastFocus.focus({preventScroll:true});hud();}
function redrawMall(){world?.destroy();world=null;renderView();hud();}
function chooseDistrict(id){pendingProduct=null;pendingReturn=null;const result=perform(()=>E.travel(s,id));if(!result.ok)return;redrawMall();}
function shopperChat(id){const n=Number(id.split('-').at(-1))||0,names=['Avery','Jordan','Casey','Riley','Morgan','Alex'],lines=['I start with a lap of the shop windows. It helps me choose what I really want.','A coffee break is part of my shopping routine. There is always time to slow down.','I keep the tags and receipt until I have decided. Returns are easier that way.','I like seeing a whole outfit come together. An outfit portrait helps me remember my favorites.','I am making a little memory today. An outfit portrait would be lovely.','I like a small detour between shops. The flower studio is my next stop.'];modal('A moment in the mall.',names[n%6]+' · Fellow shopper',`<div class="success-body"><p>${lines[n%6]}</p><button class="button orange" data-action="venue" data-id="${['popup','coffee','services','photo','photo','flowers'][n%6]}">Walk to my next stop</button><button class="button secondary" data-action="close">Enjoy your shopping</button></div>`,{small:true});}
function worldEnter(id){if(id.startsWith('commons:')){commonsTiles=[1,2,3];openCommons(id.slice(8));return;}if(id.startsWith('shopper:')){shopperChat(id);return;}if(id.startsWith('bench:')){world.restSeat=world.layout.environment?.seating.find(f=>f.id===id.slice(6))?.seat;restModal();return;}if(id.startsWith('directory:')){centerMap();return;}if(id==='amenity:notice'||id==='amenity:property'){openNeighborhood(id.slice(8));return;}if(id==='amenity:water'){waterStation();return;}if(id==='amenity:wrap'){giftWrapping();return;}if(world)world.restSeat=null;if(id.startsWith('serviceoffer:')){renderServiceStore(id.split(':')[1]);return;}const servicePrefix=['checkout:','returns:','fitting:','associate:'].find(p=>id.startsWith(p));if(servicePrefix&&E.isServiceStore(E.storeById(id.slice(servicePrefix.length)))){renderServiceStore(id.slice(servicePrefix.length));return;}if(id.startsWith('zone:')){toast('You reached '+(world?.layout.campus.nodes.find(n=>n.id===id.slice(5))?.label||'this court'));return;}if(id.startsWith('centerunit:')){enterStore(id.slice(11));return;}if(id.startsWith('checkout:')){store=id.slice(9);if(bag().length)checkoutModal();else modal('Your bag is ready when you are.',E.storeById(store).name+' · Checkout',`<div class="success-body"><p>There are no unpaid items in this store’s bag yet. Tap a real product display or browse the collection to choose something.</p><button class="button orange" data-action="back-store">Browse this store</button><button class="button secondary" data-action="close">Back to the floor</button></div>`,{small:true});return;}if(id.startsWith('returns:')){store=id.slice(8);const receipt=pendingReturn&&s.purchases.find(i=>i.id===pendingReturn&&i.store===store);pendingReturn=null;if(receipt)showReturn(receipt.id);else storeReturns();return;}if(id.startsWith('fitting:')){fittingRoom(id.slice(8));return;}if(id.startsWith('associate:')){associateModal(id.slice(10));return;}if(id.startsWith('interior:')){const id2=id.slice(9);if(!perform(()=>E.visit(s,id2)).ok){world?.leaveInterior();return;}store=id2;if(pendingCheckout===id2){pendingCheckout=null;walkStoreService('checkout');return;}if(pendingProduct||pendingReturn)enterStore(id2);else toast('Inside '+E.storeById(id2).name+' · browse the floor or meet the team.');return;}if(id.startsWith('rack:')){enterStore(id.slice(5));return;}if(id.startsWith('product:')){store=E.byId(id.slice(8)).store;detail(id.slice(8));return;}if(id.startsWith('window:')){windowModal(id.slice(7));return;}if(id.startsWith('local:')){localModal(id.slice(6));return;}if(id.startsWith('floor:')){const floor=Number(id.split(':')[1]),landing=world?.pendingLanding,trip=world?.pendingTrip,exitCallback=world?.exitCallback;if(journeyBusy){s.floor=floor;s.mapPosition={...(landing||spatialLayout(E.mallOf(s),floor,E.STORES).elevator),floor,mallId:s.mallId};save();redrawMall();world.exitCallback=exitCallback;if(trip?.length)world.resumeTrip(trip);return;}if(perform(()=>E.changeFloor(s,floor)).ok){const point=landing||spatialLayout(E.mallOf(s),floor,E.STORES).elevator;s.mapPosition={...point,floor,mallId:s.mallId};save();redrawMall();if(trip?.length)world.resumeTrip(trip);else if(pendingStore){const target=pendingStore;pendingStore=null;world.goToStore(target);}toast('Now on '+E.planFor(s).levels[floor]);}return;}if(id==='elevator'){modal('Choose a floor.',E.mallOf(s).name,`<div class="modal-body floor-choices">${E.planFor(s).levels.map((name,i)=>`<button class="button secondary wide" data-action="map-floor" data-id="${i}">${name}${i===(s.floor||0)?' · You are here':''}</button>`).join('')}</div>`,{small:true});return;}if(id.startsWith('landmark:')){landmarkModal(id.slice(9));return;}if(id.startsWith('venue:')){enterVenue(id.split(':')[1]);return;}enterStore(id);}
function focusMap(){const canvas=$('#mall-canvas');canvas?.scrollIntoView({block:'nearest',behavior:'auto'});canvas?.focus({preventScroll:true});}
function goStore(id,returnId=null){if(pendingCheckout!==id)pendingCheckout=null;if(journeyBusy||activityBusy)return;const st=E.storeById(id);if(!st)return;const destination=E.mallForStore(s,id);if(E.levelOf(s)<E.MALLS.indexOf(destination)){showView('malls');toast(`${escapeHTML(st.name)} opens at Level ${st.tier+1}.`,true);return;}pendingReturn=returnId;if(pendingProduct&&E.byId(pendingProduct)?.store!==id)pendingProduct=null;if(view!=='mall')showView('mall');closeModal();mapPanel=null;renderMapPanel();if(s.minutes>=E.CLOSE){endDay(true);return;}if(s.paused)s.paused=false;if(s.mallId!==destination.id){if(!perform(()=>E.travelMall(s,destination.id)).ok)return;redrawMall();}hud();updateMapOverlay();focusMap();if(pendingWindow===id){pendingWindow=null;world.goToWindow(id);}else world.goToStore(id);}
function enterStore(id){if(pendingReturn&&s.purchases.find(i=>i.id===pendingReturn)?.store!==id)pendingReturn=null;if(pendingProduct&&E.byId(pendingProduct)?.store!==id)pendingProduct=null;if(world?.inside!==id&&!perform(()=>E.visit(s,id)).ok)return;store=id;filter='all';storeQuery='';storeSort='featured';if(pendingCheckout===id){pendingCheckout=null;store=id;if(walkStoreService('checkout'))return;checkoutModal();return;}if(pendingReturn){if(!walkStoreService('returns')){const receipt=pendingReturn;pendingReturn=null;showReturn(receipt);}}else if(pendingProduct){const id=pendingProduct;pendingProduct=null;detail(id);}else renderStore();}
function goVenue(id){pendingCheckout=null;pendingWindow=null;pendingProduct=null;pendingReturn=null;pendingStore=null;if(view!=='mall')showView('mall');closeModal();mapPanel=null;renderMapPanel();if(!E.VENUES.some(v=>v.id===id))return;if(s.minutes>=E.CLOSE){endDay(true);return;}s.paused=false;hud();updateMapOverlay();focusMap();world.goToVenue(id);}
function enterVenue(id){if(!perform(()=>E.visitVenue(s,id)).ok)return;if(id==='coffee')coffeeShop();else if(id==='food')foodCourt();else if(id==='rest')restModal();else if(id==='popup')popupModal();else if(id==='photo')photoBooth();else if(E.ACTIVITIES.some(a=>a.venue===id))activityModal(E.ACTIVITIES.find(a=>a.venue===id).id);else if(pendingNeighborhood){const kind=pendingNeighborhood;pendingNeighborhood=null;openNeighborhood(kind);}else guestServices();}
function bag(){return cart[store]||(cart[store]=[]);}
function totals(items){return items.reduce((t,item)=>{const value=E.price(s,E.byId(item.id));t.subtotal+=value;t.tax+=Math.round(value*E.TAX);t.total+=value+Math.round(value*E.TAX);return t;},{subtotal:0,tax:0,total:0});}
function matchingProducts(items,query,category,sort){const norm=t=>String(t).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]/g,'');let result=items.filter(p=>(category==='all'||E.categoryOf(p)===category)&&(!query||norm(p.brand+' '+p.name+' '+(p.reference||'')).includes(norm(query))));if(sort==='low')result.sort((a,b)=>E.price(s,a)-E.price(s,b));else if(sort==='high')result.sort((a,b)=>E.price(s,b)-E.price(s,a));else if(sort==='name')result.sort((a,b)=>a.name.localeCompare(b.name));return result;}
function storeItems(){return matchingProducts(E.PRODUCTS.filter(p=>p.store===store),storeQuery,filter,storeSort);}
function updateStoreResults(){const items=storeItems(),locked=E.levelOf(s)<E.storeById(store).tier;$('#store-grid').innerHTML=items.length?items.map(p=>productCard(p,locked)).join(''):'<p class="no-results">No matches. Try a different product or category.</p>';$('#store-result-count').textContent=`${items.length} of ${E.storeById(store).count} real products`;$$('[data-action="filter"]').forEach(b=>b.classList.toggle('active',b.dataset.id===filter));}
function renderStore(){
 const st=E.storeById(store);if(!st){closeModal();return;}if(E.isServiceStore(st)){renderServiceStore(st.id);return;}selectedProduct=null;const locked=E.levelOf(s)<st.tier,items=storeItems(),total=totals(bag()),categories=[...new Set(E.PRODUCTS.filter(p=>p.store===store).map(E.categoryOf))];
 const room=brandDesign(st);
 const coupon=s.coupon?.store===store&&s.coupon.day===s.day;
 const banner=locked?`<div class="store-banner"><span>🔒 Browse and inspect freely. Purchases unlock at <strong>Rank ${st.tier+1} · ${E.LEVELS[st.tier].name}</strong>.</span><button class="button secondary small" data-action="play-mode" data-id="free">Try free shop</button></div>`:coupon?'<div class="store-banner">🎟 Your pavilion coupon takes 10% off this store’s game prices for one checkout today.</div>':E.sameRetailer(store,'hermes')?`<div class="store-banner"><span>Meet Luc for a 35-minute styling appointment and earn 20 XP.</span><button class="button secondary small" data-action="appointment">${s.appointmentDay===s.day?'Styling complete ✓':'Styling appointment'}</button></div>`:'';
 modal(st.name,`${st.sub} · Rank ${st.tier+1} · ${E.planFor(s).levels[s.floor||0]}`,`<div class="store-info-bar"><span>${icon('clock')} <b class="store-clock">${E.clock(s.minutes)}</b> · closes 8 PM</span><button class="text-button" data-action="store-returns">Returns desk ↗</button><span>Clock runs while browsing</span></div><div class="npc-message"><div class="npc-avatar">${st.npc[0]}</div><div><strong>${st.npc} · Shop associate · ${s.relationships[store]||0}/5 visits</strong><p>${st.greeting}</p></div></div>${banner}<details class="interior-reference"><summary>About this store’s design</summary><p>${escapeHTML(room.title)}. Original condensed game interior; individual branch layouts and finishes are adapted for play.</p>${room.cues?`<p>${room.cues.map(escapeHTML).join(' · ')}</p>`:''}${room.source?`<a href="${room.source}" target="_blank" rel="noopener noreferrer">${room.referenceKind==='brand-reference'?'Brand design reference':'Store reference'} ↗</a>`:''}</details><div class="browse-tools"><label class="search-field">${icon('eye')}<input id="store-search" type="search" placeholder="Search this store" aria-label="Search this store" value="${storeQuery.replaceAll('&','&amp;').replaceAll('"','&quot;')}"></label><select id="store-sort" aria-label="Sort store products"><option value="featured">Featured</option><option value="low" ${storeSort==='low'?'selected':''}>Price: low to high</option><option value="high" ${storeSort==='high'?'selected':''}>Price: high to low</option><option value="name" ${storeSort==='name'?'selected':''}>Product name</option></select></div><div class="store-toolbar"><strong id="store-result-count">${items.length} of ${st.count} real products</strong><div class="filter-buttons"><button class="${filter==='all'?'active':''}" data-action="filter" data-id="all">All products</button>${categories.map(cat=>`<button class="${filter===cat?'active':''}" data-action="filter" data-id="${cat}">${cat}</button>`).join('')}</div></div><div class="store-grid" id="store-grid">${items.length?items.map(p=>productCard(p,locked)).join(''):'<div class="catalog-pending"><h3>This collection is being researched.</h3><p>Only real models with matching photos and verified brand associations belong on these shelves. You can explore the interior, meet the associate, and return earlier purchases here.</p><button class="button secondary" data-action="store-returns">Return an earlier purchase</button><button class="button orange" data-action="catalog">Find a verified collection</button></div>'}</div>`,{type:'store',footer:`<div class="store-exit-strip"><button class="button secondary" data-action="leave-shop">Exit shop → Mall</button><span>Browse → choose size → review bag → pay</span></div><div class="cart-dock"><div><strong>${bag().length?`${bag().length} in your ${escapeHTML(st.name)} bag`:'Something catch your eye?'}</strong><small>${bag().length?'Eight-item carrying limit across stores':`${E.PRODUCTS.length.toLocaleString()} listings across all destinations.`}</small></div>${bag().length?`<div class="cart-total">${E.money(total.total)}<small>Including 8.25% game tax</small></div><button class="button orange" data-action="checkout">Checkout ${icon('arrow')}</button>`:'<button class="button secondary small" data-action="coffee">☕ Coffee break</button>'}</div>`});
}
function productCard(p,locked=false,context='store'){locked=locked||p.archived;const price=E.price(s,p);return `<article class="product-card"><button class="heart-button ${s.wishlist.includes(p.id)?'liked':''}" data-action="wish" data-id="${p.id}" aria-label="${s.wishlist.includes(p.id)?'Remove':'Save'} ${escapeHTML(p.name)} ${s.wishlist.includes(p.id)?'from':'to'} wishlist">${icon('heart')}</button><button class="product-open" data-action="detail" data-id="${p.id}" aria-label="View ${escapeHTML(p.name)}"><div class="product-art">${p.finalSale?'<span class="product-tag">GAME FINAL SALE</span>':price<p.price?'<span class="product-tag">TODAY’S GAME DEAL</span>':price<p.retail?'<span class="product-tag">OFF-PRICE FIND</span>':''}${picture(p)}</div></button><div class="card-body"><small>${escapeHTML(p.brand)}</small><h3>${escapeHTML(p.name)}</h3>${context==='catalog'?`<p class="catalog-store-label">${E.storeById(p.store).name} · Rank ${E.storeById(p.store).tier+1}</p>`:''}<div class="product-price">${E.money(price)}${p.retail>price?`<del>${E.money(p.retail)}</del>`:''}</div><div class="card-actions"><button class="button secondary" data-action="detail" data-id="${p.id}">${E.canTry(p)?'Inspect & try':'Inspect & demo'}</button><button class="button" data-action="quick-add" data-id="${p.id}" ${locked?'disabled':''}>+ Bag</button></div><a class="source-link" href="${p.source}" target="_blank" rel="noopener noreferrer">${sourceLabel(p)}</a></div></article>`;}
function referencePriceHTML(p){
 const date=p.referenceCheckedOn||p.observedPriceDate,amount=p.referenceAmount,currency=p.referenceCurrency||'USD';
 const label=amount?new Intl.NumberFormat('en-US',{style:'currency',currency}).format(amount)+' '+currency:E.money(p.retail)+' USD';
 if(!date)return '<p class="reference-caption">USD game price · simulated stock and discounts.</p>';
 const verified=p.referencePriceVerified??!!p.observedPriceDate;
 return `<div class="reference-price">${verified?'Published price reference':'Game price reference'}: ${escapeHTML(label)}<br><small>${escapeHTML(date)} · ${verified?'Source price can change.':'Menu price is simulated.'} Game deals and tax may differ.</small>${p.gamePriceBasis?`<p>${escapeHTML(p.gamePriceBasis)}</p>`:''}${p.conversion?`<p>Game base price converted to USD using <a href="${p.conversion.source}" target="_blank" rel="noopener noreferrer">ECB rates · ${p.conversion.date}</a>.</p>`:''}${p.priceSource?`<br><a href="${p.priceSource}" target="_blank" rel="noopener noreferrer">Published price catalog ↗</a>`:''}</div>`;
}
function associationHTML(p){const e=p.associationEvidence;if(!e)return p.archived?'<div class="hint">Earlier purchase archive. This listing has left the active catalog; existing purchases keep their game return terms.</div>':'';return `<details class="photo-source"><summary>${e.kind==='own-brand'?'Own-brand product':e.kind==='documented-carried-brand'?'Documented carried brand':'Actual merchant product'}</summary><p>${escapeHTML(e.merchant)} · ${escapeHTML(e.brand)}. ${e.kind==='documented-carried-brand'?'The source documents the retailer carrying this brand; this particular model and local stock are simulated.':'The real product reference identifies the brand or the retailer’s own listing.'} ${e.historical?'This is a dated historical brand reference; current availability is not asserted.':''}</p>${e.note?`<p>${escapeHTML(e.note)}</p>`:''}<a href="${e.source}" target="_blank" rel="noopener noreferrer">Brand association source · ${escapeHTML(e.checkedOn)} ↗</a></details>`;}

function defaultSize(p){const ideal=E.idealSize(s,p);return p.sizes.includes(ideal)&&E.stock(s,p.id,ideal)>0?ideal:p.sizes.find(size=>E.stock(s,p.id,size)>0)||p.sizes[0];}
function detail(id,keep=false){
 const p=E.byId(id);if(!p){toast('This product could not be found.',true);return;}selectedProduct=id;if(!keep){selectedSize=defaultSize(p);fitResult=null;}const value=E.price(s,p),inspected=s.seen.includes(id),matches=E.PRODUCTS.filter(q=>q.brand===p.brand&&q.name===p.name&&q.id!==id),locked=p.archived||E.levelOf(s)<E.storeById(p.store).tier;
 modal(p.name,`${escapeHTML(p.brand)} · ${E.storeById(p.store).name} · Clock paused`, `<div class="detail-body"><div class="detail-art">${picture(p,{detail:true})}${p.finalSale?'<span class="product-tag">FINAL SALE IN THIS GAME</span>':''}</div><div class="detail-info"><div class="eyebrow">REAL PRODUCT · ${p.archived?'EARLIER PURCHASE REFERENCE':'VERIFIED BRAND REFERENCE'}</div><h3>${escapeHTML(p.name)}</h3><div class="product-price">${E.money(value)}${value<p.retail?`<del>${E.money(p.retail)}</del>`:''}</div><p>${escapeHTML(p.material)}</p>${referencePriceHTML(p)}${associationHTML(p)}<a class="source-link" href="${p.source}" target="_blank" rel="noopener noreferrer">${sourceLabel(p)}</a><details class="photo-source"><summary>About the product photograph</summary><p>Real model photograph. The 3D object uses this photograph’s sampled colors and surface details with a product-specific construction profile. Shapes and prints remain adapted game art; use the photograph and reference for exact product details. Game prices and stock are simulated.</p><a href="${photos[p.id]?.source||p.source}" target="_blank" rel="noopener noreferrer">Photograph’s product reference ↗</a></details><button class="text-button saving-button" data-action="save-toward" data-id="${p.id}">${s.savingsTarget===p.id?'Your current savings goal ✓':'Save toward this real item ↗'}</button><p class="model-reference">${p.reference?'Model / set reference: '+p.reference:'Named real-world product · '+E.categoryOf(p)}</p><label class="detail-label">${p.sizes.length===1?'SIZE':'SELECT A SIZE'} · ${E.stock(s,id,selectedSize)} IN GAME STOCK</label><div class="size-options">${p.sizes.map(size=>`<button aria-pressed="${selectedSize===size}" class="size-option ${selectedSize===size?'selected':''}" data-action="size" data-id="${size}" ${E.stock(s,id,size)<=0?'disabled':''}>${size}</button>`).join('')}</div><div class="detail-actions"><button class="button secondary" data-action="try" data-id="${id}" ${E.canTry(p)?'':'disabled'}>${icon('hanger')} Try · 10 min</button><button class="button orange" data-action="add" data-id="${id}" ${locked?'disabled':''}>${icon('bag')} ${world?.inside===p.store&&physicalProduct(p)?'Pick up & carry':'Add to bag'}</button></div>${!E.canTry(p)?`<button class="button secondary wide" style="margin-top:12px" data-action="demo" data-id="${id}">${E.categoryOf(p)==='Beauty'?'Sample at the counter':'Try a product demo'} · 6 min</button>`:''}${fitResult?`<div class="fit-box ${fitResult.fits?'':'off'}"><strong>${fitResult.fits?'Fits your shopper well.':'Try a different size.'}</strong><br>${fitResult.text}</div>`:''}${inspected?`<div class="inspect-box"><strong>Label checked ✓</strong><br>${p.material}<br>${p.finalSale?'Marked final sale. No returns in this simulation.':'Keep tags attached and the item unworn for game returns.'}<br>Your usual size: ${E.idealSize(s,p)}. Fit feedback is a gameplay model, not real sizing advice.</div><button class="button secondary wide" data-action="inspect" data-id="${id}">Read label again · 3 min · 2 stamina</button>`:`<button class="button secondary wide" style="margin-top:16px" data-action="inspect" data-id="${id}">${icon('eye')} Read label · 3 min · 2 stamina</button>`}${matches.length?`<button class="button secondary wide" style="margin-top:10px" data-action="compare" data-id="${id}">${icon('tag')} Compare same product · 4 min</button>`:''}${(s.compared.includes(p.brand+' · '+p.name)||s.compared.includes(p.name))?`<div class="inspect-box"><strong>Same real product. Different game prices.</strong>${[p,...matches].sort((a,b)=>E.price(s,a)-E.price(s,b)).map(q=>`<br>${E.storeById(q.store).name}: ${E.money(E.price(s,q))}`).join('')}</div>`:''}<div class="detail-foot">Game policy: ${E.storeById(p.store).policy}-day returns, receipt and attached tags required. ${p.finalSale?'Final-sale exception applies.':''}<br>Prices, comparisons, fit, grading, store placement, and availability are simulated. Product identity is real.</div><button class="text-button detail-back" data-action="back-store">← Back to the store</button></div></div>`);
}
function addToBag(id,size){const p=E.byId(id),result=perform(()=>validatePickup(s,store,cart,id,size));if(!result.ok)return;bag().push(result.value);save();if(world?.inside===store&&physicalProduct(p)){closeModal();world.pickUpProduct(p);world.updateBagCount();toast('Picked up '+escapeHTML(p.name)+' · '+size+'. Try it on or carry it to checkout.');focusMap();}else{world?.updateBagCount?.();toast(escapeHTML(p.name)+' · '+size+' added to your bag.');renderStore();}}
function tryHeldSelection(){if(!world?.inside)return;store=world.inside;const item=bag().at(-1);if(!item){walkStoreService('fitting');return;}const p=E.byId(item.id);if(!E.canTry(p)){detail(p.id);return;}selectedProduct=p.id;selectedSize=item.size;const result=perform(()=>E.fit(s,p.id,item.size));if(result.ok){fitResult=result.value;playActivity('try','Trying '+p.name+' in the fitting room',()=>detail(p.id,true),{...p,gameSize:item.size});}}
function putBackHeld(){if(!world?.inside)return;store=world.inside;const result=perform(()=>putBackSelection(cart,store,bag().length-1));if(!result.ok)return;save();world.updateBagCount();toast(E.byId(result.value.id).name+' put back on display.');focusMap();}
function walkStoreService(kind){if(world?.inside===store&&view==='mall'){closeModal();s.paused=false;hud();updateMapOverlay();world.goToShopService(kind);focusMap();return true;}return false;}
function checkoutModal(){const items=bag();if(!items.length){renderStore();return;}const total=totals(items),queue=E.queueMinutes(s);modal('Time to make it yours.',`${E.storeById(store).name} · Checkout · Clock paused`, `<div class="modal-body">${items.map((item,i)=>{const p=E.byId(item.id);return `<div class="checkout-line"><div class="mini-art">${picture(p,{mini:true})}</div><div><strong>${escapeHTML(p.name)}</strong><small>Size ${item.size}${p.finalSale?' · GAME FINAL SALE':''}${s.tried.includes(p.id+':'+item.size)?' · Tried on ✓':''}</small></div><strong>${E.money(E.price(s,p))}</strong><button class="remove" data-action="remove-cart" data-id="${i}" aria-label="Remove ${escapeHTML(p.name)}">×</button></div>`;}).join('')}<div class="checkout-summary"><div><span>Subtotal</span><span>${E.money(total.subtotal)}</span></div><div><span>Game sales tax · 8.25%</span><span>${E.money(total.tax)}</span></div><div><span>Total</span><span>${E.money(total.total)}</span></div></div>${E.spentToday(s)+total.total>s.dailyBudget?'<div class="hint budget-warning">This checkout goes beyond your daily planning target. You can still choose to buy, or keep browsing.</div>':''}<div class="hint">⏱ ${8+items.length*2+queue} minutes · ⚡ 5 stamina${queue?'<br>The afternoon rush adds an 8-minute queue.':''}</div><button class="button orange wide" data-action="pay">Pay ${E.money(total.total)} in game money ${icon('check')}</button><p class="checkout-caption">Wallet after payment: ${E.money(s.cash-total.total)}<br>Your itemized receipt is saved automatically.</p><button class="text-button" data-action="back-store">← Keep browsing</button></div>`,{small:true});}
function pay(){const result=perform(()=>E.checkout(s,store,bag()));if(!result.ok)return;const order=result.value,foodItems=s.purchases.filter(i=>i.orderId===order.id&&['food','drink'].includes(E.byId(i.productId).type));chime();cart[store]=[];save();world?.updateBagCount?.();modal('Well found.',E.storeById(store).name+' · Receipt '+order.id,`<div class="success-body"><div class="success-icon">🛍</div><h3>${foodItems.length?'Your order is ready.':'A little more you.'}</h3><p>${foodItems.length?'Enjoy your order here, or keep it in your collection for later. Prepared food and drinks are final sale in this game.':'Your new finds are in your wardrobe.<br>Keep the tags on until you’re sure.'}</p><div class="receipt-stub">Products <b>${order.items}</b><br>Game tax <b>${E.money(order.tax)}</b><br>Total paid <b>${E.money(order.total)}</b><br>Wallet <b>${E.money(s.cash)}</b></div>${foodItems.map(i=>`<button class="button orange wide" data-action="wear" data-id="${i.id}">${E.byId(i.productId).type==='drink'?'Drink':'Eat'} ${escapeHTML(E.byId(i.productId).name)} here · 12 min</button>`).join('')}<button class="button orange" data-action="back-store">Keep shopping</button><button class="button secondary" data-action="view" data-id="wardrobe">My wardrobe</button><button class="text-button" data-action="view" data-id="missions">Check mission rewards ↗</button></div>`,{small:true});}
function renderMissions(){
 const lvl=E.levelOf(s);$('#view-root').innerHTML=`<div class="page-title"><div><h2>Your shopping story.</h2><p>${E.MISSIONS.length} chapters. Ten destinations. ${E.QUESTS.length} daily goals. The clock pauses here so you can plan.</p></div><button class="button secondary" data-action="view" data-id="mall">Back to the mall</button></div><div class="missions-layout">${missionCard(E.activeMission(s),true)}<section class="daily-board"><h3>Today’s little goals.</h3><p>Complete a goal, then collect its game-money and XP reward.</p>${E.QUESTS.map(q=>{const n=Math.min(q.target,E.dailyGoalProgress(s,q.id)),claimed=s.daily.claimed.includes(q.id),ready=n>=q.target;return `<div class="daily-row"><span class="daily-check">${claimed?'✓':ready?'✦':''}</span><div><strong>${q.detail}</strong><small>${E.money(q.cash)} + ${q.xp} XP</small></div>${ready&&!claimed?`<button class="button orange small" data-action="claim-daily" data-id="${q.id}">Collect</button>`:`<span class="daily-count">${claimed?'Collected':n+'/'+q.target}</span>`}</div>`;}).join('')}</section></div><h3 class="section-title">Your next shopping era</h3><div class="levels">${E.LEVELS.map((level,i)=>`<article class="level-card ${lvl>=i?'unlocked':''} ${lvl===i?'current':''}"><small>LEVEL ${i+1} · ${level.xp} XP</small><h3>${level.name}</h3>${icon(lvl>=i?'sparkles':'lock')}<p>${level.description}<br>${i===0?'Start with $250':E.money(level.bonus*100)+' welcome bonus'}</p></article>`).join('')}</div><h3 class="section-title">Little achievements</h3><div class="badge-grid">${E.BADGES.map(b=>`<div class="badge-card ${s.badges.includes(b.id)?'unlocked':''}"><span>${b.emoji}</span><strong>${b.name}</strong><small>${s.badges.includes(b.id)?'Earned':'Not earned yet'}</small></div>`).join('')}</div><section class="chapter-list"><h3>All ${E.MISSIONS.length} chapters</h3>${E.MISSIONS.map(m=>`<div class="chapter-row"><small>${m.chapter}</small><div><strong>${m.title}</strong><small>${m.npc}</small></div><span>${s.missions.includes(m.id)?'Completed ✓':E.activeMission(s)?.id===m.id?'In progress':'Up next'}</span></div>`).join('')}</section>${passportHTML()}`;
}
function renderWardrobe(){preview3D?.destroy();preview3D=null;cancelAnimationFrame(previewFrame);const items=wishlistOnly?E.PRODUCTS.filter(p=>s.wishlist.includes(p.id)):E.owned(s).slice().reverse();$('#view-root').innerHTML=`<div class="page-title"><div><h2>${wishlistOnly?'Your someday list.':'The dressing room.'}</h2><p>${wishlistOnly?'Real products saved for another day.':'Put together a look with the real items you bring home.'}</p></div><div class="page-actions"><button class="button secondary" data-action="wishlist-view">${icon('heart')} ${wishlistOnly?'Dressing room':'Wishlist · '+s.wishlist.length}</button><button class="button secondary" data-action="view" data-id="receipts">Receipts & returns</button></div></div>${!wishlistOnly?`<section class="dressing-room"><div class="dressing-stage"><small>${escapeHTML(s.playerName)}’S LOOK</small><canvas id="outfit-preview" width="500" height="600" aria-label="Character preview showing equipped purchased items"></canvas><div>${['left','down','right','up'].map((face,i)=>`<button class="${previewFacing===face?'active':''}" data-action="turn-preview" data-id="${face}" aria-label="View character from ${{left:'left',down:'front',right:'right',up:'back'}[face]}">${['←','Front','→','Back'][i]}</button>`).join('')}</div><div class="studio-controls" aria-label="Preview pose"><button data-action="studio-pose" data-id="stand" class="${previewPose==='stand'?'active':''}">Stand</button><button data-action="studio-pose" data-id="walk" class="${previewPose==='walk'?'active':''}">Walk</button><button data-action="studio-pose" data-id="sit" class="${previewPose==='sit'?'active':''}">Sit</button></div><div class="studio-controls" aria-label="Preview framing"><button data-action="studio-camera" data-id="body" class="${previewFocus==='body'?'active':''}">Whole outfit</button><button data-action="studio-camera" data-id="face" class="${previewFocus==='face'?'active':''}">Face & hair</button></div><p>Live character · real products · Stand, walk or sit to check your look</p></div><div class="equipment-slots"><h3>Make it your own.</h3><p>Mix a top, bottoms, shoes, a bag, and accessories. Equipped purchases stay visible while you shop and walk home.</p>${Object.entries(E.SLOT_NAMES).map(([slot,name])=>{const item=E.owned(s).find(i=>i.id===s.equipment[slot]),p=item&&E.byId(item.productId);return `<div class="equipment-slot"><span>${name}</span><strong>${p?escapeHTML(p.brand+' '+p.name):(['top','bottom','shoes'].includes(slot)?'Your base '+name.toLowerCase():'None equipped')}</strong>${p?`<button data-action="unequip" data-id="${slot}" aria-label="Remove equipped ${name.toLowerCase()}">Remove ×</button>`:'<small>Equip a purchase below</small>'}</div>`;}).join('')}<button class="text-button" data-action="settings">Change name, hair & base colors ↗</button></div></section><div class="section-head"><h3>Your collection · ${items.length} kept purchases</h3><button class="text-button" data-action="view" data-id="mall">Find something new ↗</button></div>`:''}${!items.length?`<div class="empty">${icon(wishlistOnly?'heart':'hanger')}<h3>${wishlistOnly?'Something will catch your eye.':'Your first look starts at the outlets.'}</h3><p>Save items with a heart, or bring home a purchase to begin your collection.</p><button class="button orange" data-action="view" data-id="mall">Explore the shops ${icon('arrow')}</button></div>`:`<div class="wardrobe-grid">${items.map(item=>{if(wishlistOnly)return productCard(item,E.levelOf(s)<E.storeById(item.store).tier);const p=E.byId(item.productId),elig=E.returnEligibility(s,item),wearing=E.equipped(s).includes(item.id),slot=E.slotForProduct(p);return `<article class="product-card"><div class="product-art">${wearing?'<span class="product-tag">EQUIPPED ✓</span>':''}${picture(p)}</div><div class="card-body"><small>${escapeHTML(p.brand)} · SIZE ${item.size}${slot?' · '+E.SLOT_NAMES[slot].toUpperCase():''}</small><h3>${escapeHTML(p.name)}</h3><div class="product-price">${E.money(item.total)}</div><p>${item.checked?'📦 Waiting at concierge':item.tags?'Unused · tags / packaging intact':elig.reason}</p><div class="wardrobe-card-actions"><button class="button ${wearing?'orange':'secondary'}" data-action="${item.worn?'wear':'wear-confirm'}" data-id="${item.id}" ${item.checked||wearing?'disabled':''}>${wearing?'Equipped ✓':slot?'Equip '+E.SLOT_NAMES[slot].toLowerCase():item.worn?'Used ✓':'Open & use'}</button>${elig.ok?`<button class="button secondary" data-action="take-return" data-id="${item.id}">Return ↗</button>`:''}</div><a class="source-link" href="${p.source}" target="_blank" rel="noopener noreferrer">Real product source ↗</a></div></article>`;}).join('')}</div>`}`;if(!wishlistOnly){$('.page-title').insertAdjacentHTML('afterend',lifeLinksHTML());$('.dressing-room').insertAdjacentHTML('afterend',lookbookHTML());drawOutfitPreview();}}
function drawOutfitPreview(){cancelAnimationFrame(previewFrame);let canvas=$('#outfit-preview');if(!canvas)return;if(s.preferences.graphics!=='2d'){try{preview3D=new CharacterStudio(canvas,s,{facing:previewFacing,pose:previewPose,focus:view==='collections'?'room':previewFocus,setting:view==='collections'?'home':'studio'});return;}catch(error){console.warn('Character studio unavailable; using the light preview.',error);const replacement=canvas.cloneNode();canvas.replaceWith(replacement);canvas=replacement;}}$$('.studio-controls').forEach(el=>el.hidden=true);$$('[data-action=room-walk]').forEach(el=>el.disabled=true);const walkStatus=$('#room-walk-status');if(walkStatus)walkStatus.textContent='Walking is available in 3D. Your shelf and evening routine work in this view.';canvas.setAttribute('aria-label',view==='collections'?'Illustrated shopper preview for your collection room':'Illustrated outfit preview');canvas.dataset.characterModel='illustrated';const c=canvas.getContext('2d');const draw=t=>{if(!canvas.isConnected)return;c.setTransform(1,0,0,1,0,0);c.fillStyle='#e3e9d6';c.fillRect(0,0,canvas.width,canvas.height);const k=Math.min(canvas.width/500,canvas.height/600);c.setTransform(k,0,0,k,(canvas.width-500*k)/2,(canvas.height-600*k)/2);c.clearRect(0,0,500,600);const gradient=c.createLinearGradient(0,0,0,600);gradient.addColorStop(0,view==='collections'?(E.ROOM_STYLES.find(v=>v.id===s.roomStyle)?.wall||'#e3e9d6'):'#e3e9d6');gradient.addColorStop(1,'#f7edda');c.fillStyle=gradient;c.fillRect(0,0,500,600);c.strokeStyle='#b7c5a5';c.lineWidth=3;c.strokeRect(42,32,416,485);c.fillStyle='#c2ccb3';c.beginPath();c.ellipse(250,500,140,28,0,0,7);c.fill();c.save();c.translate(250,490);c.scale(5.4,5.4);paintPerson(c,0,0,{appearance:s.appearance,equipment:E.equippedLook(s),player:true,facing:previewFacing,time:t/1000});c.restore();previewFrame=requestAnimationFrame(draw);};previewFrame=requestAnimationFrame(draw);}
function renderReceipts(){const orders=s.orders;$('#view-root').innerHTML=`<div class="page-title"><div><h2>The paper trail.</h2><p>Return unworn items with tags at the original store within its game return window. Original tax is refunded too.</p></div></div>${!orders.length?`<div class="empty">${icon('receipt')}<h3>No receipts. Yet.</h3><p>Your purchases and return deadlines will appear here.</p><button class="button orange" data-action="view" data-id="mall">Find your first good thing</button></div>`:`<div class="receipt-list">${orders.map(o=>`<article class="receipt-card"><div class="receipt-header"><div><strong>${E.storeById(o.store).name}</strong><small>DAY ${o.day} · ${E.clock(o.minutes)} · RECEIPT ${o.id}</small></div>${icon('receipt')}</div>${s.purchases.filter(p=>p.orderId===o.id).map(item=>{const p=E.byId(item.productId),elig=E.returnEligibility(s,item);return `<div class="receipt-line"><div class="mini-art">${picture(p,{mini:true})}</div><div class="receipt-line-info"><strong>${escapeHTML(p.name)} · ${E.money(item.total)}</strong><small>SIZE ${item.size} · ${elig.reason}</small></div>${elig.ok?`<button class="button secondary small" data-action="take-return" data-id="${item.id}">Take to store ${icon('return')}</button>`:`<small style="color:#99a485">${item.returned?'Refunded ✓':'Not returnable'}</small>`}</div>`;}).join('')}<div class="receipt-total">${E.money(o.subtotal)} + ${E.money(o.tax)} tax <b>${E.money(o.total)}</b></div></article>`).join('')}</div>`}`;}
function showReturn(id){const item=s.purchases.find(p=>p.id===id);if(!item)return;const p=E.byId(item.productId),elig=E.returnEligibility(s,item);modal('A change of heart.',`${E.storeById(item.store).name} · Returns desk`, `<div class="modal-body"><div class="checkout-line"><div class="mini-art">${picture(p,{mini:true})}</div><div><strong>${escapeHTML(p.name)}</strong><small>Size ${item.size} · Receipt ${item.orderId}</small><small>${elig.reason}</small></div></div><div class="checkout-summary"><div><span>Item price</span><span>${E.money(item.price)}</span></div><div><span>Tax refund</span><span>${E.money(item.tax)}</span></div><div><span>Back to your wallet</span><span>${E.money(item.total)}</span></div></div><p>${elig.ok?'The associate checks your receipt, tags, and the item’s unworn condition. Your return qualifies for a full refund.':elig.reason+'. This item cannot be refunded in the game.'}</p><div class="hint">⏱ 10 minutes · ⚡ 3 stamina<br>Game return policies are simplified, not actual retailer advice.</div>${elig.ok?`<button class="button orange wide" data-action="refund" data-id="${id}">Return & refund ${E.money(item.total)}</button>`:''}<button class="text-button" style="margin-top:18px" data-action="back-store">← Back to the shop</button></div>`,{small:true});}
function storeReturns(){const items=s.purchases.filter(p=>p.store===store&&!p.returned);modal('Returns desk.',E.storeById(store).name,`<div class="modal-body">${!items.length?'<p>No eligible purchases from this store yet.</p>':items.map(item=>{const p=E.byId(item.productId),elig=E.returnEligibility(s,item);return `<div class="checkout-line"><div class="mini-art">${picture(p,{mini:true})}</div><div><strong>${escapeHTML(p.name)}</strong><small>${elig.reason}</small></div><button class="button secondary small" data-action="return-detail" data-id="${item.id}" ${!elig.ok?'disabled':''}>Return</button></div>`;}).join('')}<button class="text-button" style="margin-top:18px" data-action="back-store">← Back to browsing</button></div>`,{small:true});}
function foodCourt(){modal('A well-earned lunch break.',`Nora’s food court · Fullness ${Math.ceil(s.hunger)}/100 · Stamina ${Math.ceil(s.energy)}/100`, `<div class="modal-body"><div class="hint">Food restores fullness. Coffee restores stamina, but it won’t feed you. A meal uses game time; this menu pauses the running clock.</div><div class="meal-list">${E.FOOD.map(food=>`<article class="meal-card"><span aria-hidden="true">${food.emoji}</span><div><strong>${food.name}</strong><p>${food.description}</p><div class="meal-effects"><span>⏱ ${food.minutes} min</span><span>🥪 +${food.hunger}</span><span>⚡ +${food.energy}</span></div></div><button class="button ${food.price?'orange':'secondary'}" data-action="eat" data-id="${food.id}">${food.price?E.money(food.price):'Free'}</button></article>`).join('')}</div><p class="footer-balance">Your wallet: ${E.money(s.cash)}</p></div>`,{small:true});}
function restModal(){modal('Find a quiet corner.', 'A bench, a little shade, and no reason to hurry.', `<div class="success-body"><div class="rest-illustration" aria-hidden="true">🌳 🪑</div><h3>Put your bags down.</h3><p>Rest for 30 game minutes to recover up to 38 stamina.<br>You’ll get a little hungrier while time passes.</p><div class="care-summary"><span>⏱ 30 minutes</span><span>⚡ +38</span><span>Free</span></div><button class="button orange" data-action="rest-now">Sit & rest</button><button class="button secondary" data-action="food">Get lunch instead</button></div>`,{small:true});}
function endDay(forced=false){const pay=18000+E.levelOf(s)*10000,healthy=s.energy>=25&&s.hunger>=25;modal(forced?'The mall is closing.':'Call it a good day?',`DAY ${s.day} · ${E.clock(s.minutes)}`,`<div class="success-body"><div class="success-icon">🏡</div><h3>Your bed is calling.</h3><p>Walk to the exit, stroll home, put down your bags, and sleep. Your next day includes a simulated work-shift paycheck.<br>You can watch the evening routine or skip its animation. Tomorrow brings breakfast, fresh stock, and new requests.</p><div class="recap-grid"><div class="recap-cell"><small>Today’s purchases</small><strong>${s.orders.filter(o=>o.day===s.day).length}</strong></div><div class="recap-cell"><small>Daily rewards collected</small><strong>${s.daily.claimed.length} / ${E.QUESTS.length}</strong></div><div class="recap-cell"><small>Work-shift pay</small><strong>${E.money(pay)}</strong></div><div class="recap-cell"><small>Fed & rested finish</small><strong>${healthy?'Yes 🌿':'Below 25'}</strong></div></div><p class="catalog-note">Unpaid bags are cleared. Return deadlines move forward one day. Collected missions and purchases stay saved.</p><button class="button secondary" data-action="view" data-id="collections">Visit my room & evening routine</button><button class="button orange" data-action="next-day">Walk home & sleep ${icon('arrow')}</button>${forced?'':`<button class="button secondary" data-action="close">Keep exploring</button>`}</div>`,{small:true});}
function help(){modal('A cozy day, with a little strategy.', 'Explore. Eat. Rest. Find something you love.',`<div class="modal-body">${[['🕰','A day from 10 AM to 8 PM','One real second passes one game minute while exploring or browsing stores. You can pause anytime. Product details, missions, meals, and hidden browser tabs pause the live clock.'],['🥪','Take care of your shopper','Time reduces fullness and stamina. Shopping costs extra stamina. At low fullness, stamina falls faster; at 5 fullness you need food before more shopping. Food court meals start at $4; water and bench rests are free.'],['🛍','Shop real products','Every catalog name refers to a real product. Inspect its label, compare matching products, select your size, and try it on. Pay with game money and keep your receipt. Prices, stock, fit feedback, and store placement are simulated.'],['🧾','Change your mind thoughtfully','Bring unworn items with tags back to the original store within 30 game days. Tax is refunded too. Marked final-sale items and worn items cannot be returned.'],['📒','Build your shopping story','Finish twenty-four story chapters and collect their rewards. Ten daily goals refresh each morning. Earn XP to unlock new stores and collect badges for good shopping habits.'],['🏡','Call it a day','Head home before the mall closes. Sleep restores your needs; a simulated off-screen work shift adds money for tomorrow. Keep both needs at least 25 for a fed-and-rested day.']].map(([emoji,title,text])=>`<div class="help-row"><span>${emoji}</span><div><strong>${title}</strong><p>${text}</p></div></div>`).join('')}<button class="button orange wide" style="margin-top:22px" data-action="interactive-guide">Open the interactive shopping guide</button><button class="button secondary wide" data-action="close">Let’s go for a wander</button><button class="text-button" data-action="sources">Product sources & game details ↗</button></div>`,{small:true});}
function sources(){const brands=[...new Set(E.PRODUCTS.map(p=>p.brand))];modal('Real products. A simulated shopping day.', 'Catalog identity checked against official brand sources · '+E.CHECKED_ON,`<div class="modal-body"><div class="hint">All ${E.PRODUCTS.length} catalog entries refer to named products that exist in the real world. Some are earlier-generation or archive models. Off-price store assignments are gameplay fixtures, not claims that a particular Ross or Marshalls currently stocks them.</div><p>Product names and basic descriptions come from the linked brand pages. All merchandise cards use real product photographs, with source records and variant notes. Some archived models use documented retailer photographs. Character equipment and scenery are stylized game art. Game prices, compare-at values, stock, sizing feedback, deadlines, final-sale flags, appointments, and mission payouts are designed for play.</p><div class="sources-list">${brands.map(brand=>{const items=E.PRODUCTS.filter(p=>p.brand===brand);return `<div><strong>${brand}</strong>${[...new Map(items.map(p=>[p.name,p])).values()].map(p=>`<div><a href="${p.source}" target="_blank" rel="noopener noreferrer">${escapeHTML(p.name)} ↗</a></div>`).join('')}</div>`;}).join('')}</div><p class="catalog-note">Independent fan-made game, not affiliated with these brands. No real purchases or payments. Progress stays in browser storage; it does not sync across devices. Opening a brand source leaves the simulation.</p></div>`,{small:true});}
function catalogStoreOptions(){const id=catalogMall==='current'?s.mallId:catalogMall;if(id==='all')return E.STORES;const ids=new Set(E.mallById(id).sections.flatMap(d=>d.stores));return E.STORES.filter(st=>ids.has(st.id));}
function catalogMatches(){let items=catalogStore==='all'?catalogStoreOptions().flatMap(st=>st.products):E.productsForStore(catalogStore);if(catalogStore==='all'){const unique=new Map(),here=new Set(E.mallOf(s).sections.flatMap(d=>d.stores)),rank=p=>here.has(p.store)?-1:E.storeById(p.store).tier;for(const p of items){const key=p.brand+' · '+p.name,prior=unique.get(key);if(!prior||rank(p)<rank(prior)||rank(p)===rank(prior)&&p.price<prior.price)unique.set(key,p);}items=[...unique.values()];}if(affordableOnly)items=items.filter(p=>E.price(s,p)+Math.round(E.price(s,p)*E.TAX)<=s.cash);return matchingProducts(items,catalogQuery,catalogCategory,catalogSort);}
function updateCatalogResults(){const items=catalogMatches(),shown=items.slice(0,catalogLimit);$('#catalog-results').innerHTML=shown.length?shown.map(p=>productCard(p,E.levelOf(s)<E.storeById(p.store).tier,'catalog')).join(''):'<div class="no-results">No products match those filters. Try another name, store, or category.</div>';$('#catalog-result-count').textContent=`${items.length} real models · showing ${shown.length}`;$('#catalog-more').innerHTML=items.length>shown.length?`<button class="button secondary" data-action="more-catalog">Show 24 more products</button>`:'';}
function renderCatalog(){const categories=[...new Set(E.PRODUCTS.map(E.categoryOf))];$('#view-root').innerHTML=`<div class="page-title"><div><h2>One world. So much to discover.</h2><p>${E.STORES.length.toLocaleString()} playable shops and service locations, with ${E.UNIQUE_MODELS} distinct photographed product models. Search by name or brand, then visit the store to inspect or buy.</p></div><button class="button secondary" data-action="view" data-id="mall">Center map ${icon('map')}</button></div><div class="catalog-travel-banner"><div><strong>${s.sandbox?'All destinations unlocked':'Your level '+(E.levelOf(s)+1)} · ${E.mallOf(s).name}</strong><small>${s.sandbox?'Browse freely, or follow the story at your own pace.':'Earn XP to unlock more shopping destinations.'}</small></div><button class="button secondary" data-action="view" data-id="malls">Destinations & unlocks ↗</button></div><section class="catalog-browser"><div class="section-head"><h3>Browse every real model</h3><span>GAME PRICES & INVENTORY</span></div><div class="catalog-controls"><label class="search-field">${icon('eye')}<input type="search" id="catalog-search" aria-label="Search all real products" placeholder="Search Levi’s, AirPods, LEGO, Tabby…" value="${catalogQuery.replaceAll('&','&amp;').replaceAll('"','&quot;')}"></label><select id="catalog-mall" aria-label="Filter catalog by mall"><option value="current" ${catalogMall==='current'?'selected':''}>Current mall</option><option value="all" ${catalogMall==='all'?'selected':''}>All destinations</option>${E.MALLS.map(m=>`<option value="${m.id}" ${catalogMall===m.id?'selected':''}>${m.name}</option>`).join('')}</select><select id="catalog-store" aria-label="Filter catalog by store"><option value="all">All shops in this selection</option>${catalogStoreOptions().filter(st=>st.count).map(st=>`<option value="${st.id}" ${catalogStore===st.id?'selected':''}>${escapeHTML(st.name)}${catalogMall==='all'&&st.mallId?' · '+E.mallById(st.mallId).name:''}</option>`).join('')}</select><select id="catalog-category" aria-label="Filter catalog by category"><option value="all">All categories</option>${categories.map(cat=>`<option ${catalogCategory===cat?'selected':''}>${cat}</option>`).join('')}</select><select id="catalog-sort" aria-label="Sort catalog products"><option value="featured">Featured</option><option value="low" ${catalogSort==='low'?'selected':''}>Price: low to high</option><option value="high" ${catalogSort==='high'?'selected':''}>Price: high to low</option><option value="name" ${catalogSort==='name'?'selected':''}>Product name</option></select></div><div class="catalog-subline"><span id="catalog-result-count"></span><label><input type="checkbox" id="catalog-budget" ${affordableOnly?'checked':''}> Within my game budget, including tax</label></div><div id="catalog-results" class="catalog-grid"></div><div id="catalog-more" class="load-more"></div></section>`;updateCatalogResults();}
function passportHTML(){return `<section class="passport-board"><div class="section-head"><h3>Your shopping-center passport</h3><span>${E.CORE_STORES.filter(st=>E.visitedRetailer(s,st.id)).length} / ${E.CORE_STORES.length} STORY RETAILERS VISITED</span></div><div class="passport-districts">${E.DISTRICTS.map(d=>`<article><h4>${d.emoji} ${d.name}</h4>${E.CORE_STORES.filter(st=>st.district===d.id).map(st=>`<span class="passport-stamp ${E.visitedRetailer(s,st.id)?'stamped':''}">${E.visitedRetailer(s,st.id)?'✓':'○'} ${escapeHTML(st.name)}</span>`).join('')}</article>`).join('')}</div><div class="passport-extras"><span>☕ ${s.metrics.coffees} coffee orders</span><span>🎪 ${s.popupStamps.length} pavilion stamps</span><span>📷 ${new Set(s.postcards.map(p=>p.district)).size}/${E.DISTRICTS.length} district postcards</span><span>🧪 ${s.demos.length} products tested</span></div></section>`;}
function coffeeShop(){modal('A coffee before the next lap.',`Starbucks coffee stop · Market Walk · ${s.metrics.coffees} coffee orders in your passport`,`<div class="modal-body"><div class="hint">Real Starbucks drink and pastry names, with simulated prices and recovery effects. Coffee restores stamina; the croissant also helps with fullness. <a href="https://about.starbucks.com/stories/2025/espresso-explained/" target="_blank" rel="noopener noreferrer">Official espresso guide ↗</a></div><div class="meal-list">${E.COFFEE_MENU.map(drink=>`<article class="meal-card"><span>${drink.emoji}</span><div><strong>${drink.name}</strong><p>${drink.description}</p><div class="meal-effects"><span>⏱ ${drink.minutes} min</span><span>🥪 +${drink.hunger}</span><span>⚡ +${drink.energy}</span></div></div><button class="button orange" data-action="coffee-order" data-id="${drink.id}">${E.money(drink.price)}</button></article>`).join('')}</div><p class="footer-balance">Your wallet: ${E.money(s.cash)}</p></div>`,{small:true});}
function popupModal(){const event=E.currentPopup(s),claimed=s.popupStamps.some(p=>p.day===s.day),stockist=E.storeById(event.store);modal(event.title,`The Pop-Up Pavilion · ${event.host} · Day ${s.day}`,`<div class="popup-intro"><span>🎪</span><div><h3>${event.host}</h3><p>${event.description}</p><small>A fictional in-game showcase of real products. The exhibit rotates each game day.</small></div></div><div class="popup-reward"><div><strong>${claimed?'Today’s stamp is in your passport.':'A little curiosity pays off.'}</strong><p>${claimed?`Your coupon is valid at ${stockist.name} until tonight, unless already used.`:`Spend 10 game minutes here to collect a stamp, 20 XP, and a 10% game coupon for one ${stockist.name} checkout today.`}</p></div><button class="button ${claimed?'secondary':'orange'}" data-action="popup-claim" ${claimed?'disabled':''}>${claimed?'Stamp collected ✓':'Collect stamp & coupon'}</button></div><div class="store-grid popup-grid">${event.products.map(id=>{const p=E.byId(id);return `<article class="product-card"><div class="product-art">${picture(p)}</div><div class="card-body"><small>${escapeHTML(p.brand)} · REAL PRODUCT</small><h3>${escapeHTML(p.name)}</h3><p>Stockist: ${stockist.name} · Rank ${stockist.tier+1}</p><div class="product-price">${E.money(E.price(s,p))}</div><div class="card-actions"><button class="button secondary" data-action="demo" data-id="${p.id}">Try exhibit · 6 min</button><button class="button" data-action="visit" data-id="${p.store}">Visit shop ↗</button></div><a class="source-link" href="${p.source}" target="_blank" rel="noopener noreferrer">Official model source ↗</a></div></article>`;}).join('')}</div>`,{type:'detail'});}
function photoBooth(){renderPhotoBooth();}
function applyPreferences(){const pref=s.preferences;pref.reducedMotion=pref.motion==='reduced'||(pref.motion==='system'&&matchMedia('(prefers-reduced-motion: reduce)').matches);document.body.classList.toggle('reduced-motion',pref.reducedMotion);document.body.classList.toggle('large-text',!!pref.largeText);}
function chime(){if(!s.preferences.sound)return;try{audioContext??=new (window.AudioContext||window.webkitAudioContext)();audioContext.resume();for(const [i,note] of [523.25,659.25].entries()){const o=audioContext.createOscillator(),g=audioContext.createGain(),t=audioContext.currentTime+i*.1;o.type='sine';o.frequency.value=note;g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(.035,t+.015);g.gain.exponentialRampToValueAtTime(.0001,t+.25);o.connect(g);g.connect(audioContext.destination);o.start(t);o.stop(t+.26);}}catch{}}
function renderMainMenu(){const mall=E.mallOf(s),level=E.levelOf(s);$('#view-root').innerHTML=`<section class="menu-v5"><div class="menu-intro"><span class="eyebrow">MALLSIDE · A SHOPPING LIFE</span><h1>A little shopping.<br>A whole lot<br>of possibilities<span>.</span></h1><p>Explore a whole shopping center in 3D. Follow its wings, cross between buildings, browse real designs, and take a seat between finds.</p><div class="menu-play"><button class="button orange" data-action="resume-game">${s.nightPending===s.day?'Continue the walk home':'Continue '+(s.sandbox?'free shop':'your story')} ${icon('arrow')}<small>Day ${s.day} · ${mall.name} · ${E.money(s.cash)}</small></button><div><button class="button secondary" data-action="play-mode" data-id="career">Career · earn every destination</button><button class="button secondary" data-action="play-mode" data-id="free">Free shop · explore everything</button></div></div><div class="menu-options"><button data-action="new-career">New career</button><button data-action="settings">Player & options</button><button data-action="view" data-id="journal">Plan today’s outing</button><button data-action="help">How to play</button><button data-action="view" data-id="collections">My collection room</button><button data-action="fullscreen">⛶ Fullscreen</button></div></div><div class="menu-world"><div class="city-sky"><span>☀</span><i></i><i></i><i></i><b>YOUR NEXT GREAT FIND IS OUT THERE</b></div><div class="city-shops">${[['ROSS','#a65f4c'],['UNIQLO','#b84b3e'],['COACH','#6e8874'],['LOUIS VUITTON','#977856']].map(([name,col])=>`<div style="--shop:${col}"><b>${name}</b><span>✧</span><i></i></div>`).join('')}</div><div class="city-promenade"><span>🌴</span><span>🌷</span><span>⛲</span><span>🌴</span></div><div class="menu-passport"><span>${mall.emoji}</span><div><small>${s.sandbox?'FREE SHOP · ALL DESTINATIONS':'LEVEL '+(level+1)+' · '+s.xp+' XP'}</small><strong>${mall.name}</strong><p>${E.LEVELS[level+1]?Math.max(0,E.LEVELS[level+1].xp-s.xp)+' XP to '+E.LEVELS[level+1].name:'Your whole shopping world is open.'}</p></div><button data-action="view" data-id="malls" aria-label="Open destination passport">↗</button></div></div></section><div class="menu-discover"><div><strong>10</strong><span>distinct mall destinations</span></div><div><strong>${E.UNIQUE_MODELS}</strong><span>real models with product photos</span></div><div><strong>9</strong><span>visible outfit slots</span></div><div><strong>${E.MISSIONS.length}</strong><span>story chapters + ${E.LOCALS.length*3} friendship + ${E.LOCAL_STORIES.length*E.LOCAL_STORY_CHAPTERS} local chapters</span></div></div><div class="menu-foot"><p>Career and free shop save separately on this browser. Export a backup in Player & options.</p><button class="text-button" data-action="research">The real-world inspirations ↗</button><a class="text-button" href="legal.html" target="_blank" rel="noopener noreferrer">Rights & privacy ↗</a></div>`;}
function renderMalls(){const level=E.levelOf(s);$('#view-root').innerHTML=`<div class="page-title"><div><span class="eyebrow">YOUR DESTINATION PASSPORT</span><h2>One city. Ten shopping worlds.</h2><p>Earn XP from discoveries, chapters, daily goals, and requests. Each level opens a new mall.</p></div><button class="button secondary" data-action="view" data-id="missions">Earn XP & claim rewards ↗</button></div><div class="passport-progress"><strong>Level ${level+1} / ${E.LEVELS.length}</strong><span>${s.visitedMalls.length} / 10 destinations visited · ${s.xp} XP</span><div class="progress"><i style="width:${s.sandbox?100:Math.min(100,s.xp/E.LEVELS.at(-1).xp*100)}%"></i></div></div><div class="mall-cards">${E.MALLS.map((m,i)=>{const locked=level<i,current=s.mallId===m.id,goal=E.destinationGoal(s,m.id);return `<article class="mall-destination ${locked?'locked':''}" style="--mall:${m.color};--mall-ground:${m.ground}"><div class="mall-postcard"><small>DESTINATION ${String(i+1).padStart(2,'0')}</small><span>${m.emoji}</span><div class="postcard-buildings"><i></i><i></i><i></i></div><b>${m.landmark}</b></div><div class="mall-card-copy"><small>LEVEL ${i+1} · ${m.xp.toLocaleString()} XP ${s.visitedMalls.includes(m.id)?'· VISITED ✓':''}</small><h3>${m.name}</h3><a href="${m.source}" target="_blank" rel="noopener noreferrer">Inspired by ${m.inspiration} ↗</a><p>${m.description}</p><div class="mall-contents"><b>${CENTER_DIRECTORIES[m.id]?.tenants.length||0} directory entries · ${E.planFor({mallId:m.id}).levels.length} floor views</b><span>${new Set(m.sections.flatMap(d=>d.stores)).size} playable shops & service locations</span><span>${E.planFor({mallId:m.id}).anchors.slice(0,3).map(a=>a.name).join(' · ')}</span></div><div class="destination-goals"><strong>Destination discovery reward</strong><span>${goal.visited?'✓':'○'} Travel here · ${Math.min(2,goal.visits)}/2 shops visited · ${Math.min(goal.target,goal.inspects)}/${goal.target} labels read</span><button class="text-button" data-action="claim-destination" data-id="${m.id}" ${!goal.ready||goal.claimed?'disabled':''}>${goal.claimed?'Passport reward collected ✓':goal.xp+' XP + '+E.money(goal.cash)+' · '+(goal.ready?'Collect reward':'Keep exploring')}</button></div><button class="button ${locked?'secondary':'orange'} wide" data-action="travel-mall" data-id="${m.id}" ${locked?'disabled':''}>${locked?'🔒 '+(m.xp-s.xp).toLocaleString()+' XP to unlock':current?'Continue exploring →':'Travel here · 20 game min →'}</button></div></article>`;}).join('')}</div><p class="catalog-note">These are original game destinations inspired by real centers. The unlock order, layouts, store placement, merchandise, and economy are game design. This is not a ranking or a live directory of the actual malls.</p>`;}
function playActivity(kind,caption,after=()=>{},previewProduct=null){if(recovery)return;if(activityBusy)return;if(world?.animate&&view==='mall'){closeModal();activityBusy=true;setGameInert(true);$('#journey-root').innerHTML=`<div class="departure-bar scene-activity" role="status"><span>${escapeHTML(caption)}</span>${kind==='try'&&world.inside?'<button class="button secondary small" data-action="fitting-turn">Turn ↻</button>':''}<button class="button secondary small" data-action="skip-activity">${kind==='try'&&world.inside?'Done trying':'Finish moment'}</button></div>`;const done=()=>{if(!activityBusy)return;activityBusy=false;activityScene=null;$('#journey-root').innerHTML='';setGameInert(false);hud();focusMap();after();};if(kind==='try'&&world.inside){activityScene={finish:()=>world?.finishFitting()};world.startFitting(previewProduct,done);}else{activityScene={finish:()=>world?.finishAnimation()};world.animate(kind,done,{previewProduct,horseIndex:previewProduct?.memory?.choice?.horse||0});}hud();return;}closeModal();activityBusy=true;setGameInert(true);$('#journey-root').innerHTML=`<div class="journey-overlay activity-overlay"><section class="night-card" role="dialog" aria-modal="true" aria-label="${caption}"><header><div><small>A LITTLE MOMENT IN YOUR DAY</small><h2>${caption}</h2></div><button class="button secondary small" data-action="skip-activity">Skip animation</button></header><canvas class="activity-scene" width="1200" height="600" aria-label="Animated character ${kind==='rest'?'walking to a bench, sitting down and resting':kind==='icecream'?'sitting and eating an ice cream cone':kind==='drink'?'sitting and drinking coffee':kind==='window'?'walking to a window and examining a real product':kind==='chat'?'talking with another shopper':'enjoying a break'}"></canvas><p data-activity-caption role="status" aria-live="polite">Walking into a little moment…</p></section></div>`;$('#journey-root button').focus();const done=()=>{if(!activityBusy)return;activityBusy=false;activityScene?.destroy();activityScene=null;$('#journey-root').innerHTML='';setGameInert(false);hud();after();};activityScene=new ActivityScene($('.activity-scene'),s,kind,done);activityScene.previewProduct=previewProduct;activityScene.finish=done;hud();}
function openMainMenu(){if(journeyBusy||activityBusy)return;showView('menu');save();}
function resumeGame(){showView('mall');if(s.nightPending===s.day)startNight(true);else if(!s.v9Welcome)welcomeTrip();}
function playMode(nextMode){if(journeyBusy||!switchSave(nextMode))return;if(!recovery)resumeGame();}
function settings(){if(recovery){renderRecovery();return;}const select=(key,values)=>`<select data-pref="${key}" aria-label="${key==='clockSeconds'?'Game clock speed':key==='walkSpeed'?'Walking speed':key==='graphics'?'Graphics mode':'Animation preference'}">${values.map(([value,label])=>`<option value="${value}" ${String(s.preferences[key])===String(value)?'selected':''}>${label}</option>`).join('')}</select>`;modal('Your shopper. Your pace.', 'Changes save automatically for this mode.',`<div class="modal-body"><div class="profile-preview"><div class="tiny-avatar" style="--skin:${s.appearance.skin};--hair:${s.appearance.hair};--shirt:${s.appearance.shirt};--bag:${s.appearance.bag}"><i></i><b></b><em></em><span></span></div><div><label for="player-name">Shopper name</label><input id="player-name" maxlength="20" value="${escapeHTML(s.playerName)}" aria-label="Shopper name"><small>Your character uses these colors and styles.</small></div></div><div class="color-options">${[['skin','Skin tone'],['hair','Hair color'],['shirt','Outfit color'],['bag','Shopping bag color']].map(([key,label])=>`<label>${label}<input type="color" data-appearance="${key}" value="${s.appearance[key]}" aria-label="${label}"></label>`).join('')}</div><div class="settings-row"><label for="hair-style">Haircut</label><select id="hair-style" data-character-style="hairStyle" aria-label="Haircut"><option value="short" ${s.appearance.hairStyle!=='bob'?'selected':''}>Textured short hair</option><option value="bob" ${s.appearance.hairStyle==='bob'?'selected':''}>Chin-length bob</option></select></div><div class="settings-row"><label for="face-style">Face detail</label><select id="face-style" data-character-style="faceStyle" aria-label="Face detail"><option value="natural" ${s.appearance.faceStyle!=='defined'?'selected':''}>Soft features</option><option value="defined" ${s.appearance.faceStyle==='defined'?'selected':''}>Defined features</option></select></div>${[['size','Clothing size',['XS','S','M','L','XL']],['shoeSize','US shoe size',['6','7','8','9','10']],['waist','Jeans waist',['28','30','32','34','36']],['ringSize','Ring size',['5','6','7','8','9']]].map(([key,label,values])=>`<div class="settings-row"><label>${label}</label><select data-setting="${key}" aria-label="${label}">${values.map(v=>`<option ${String(s[key]||'7')===v?'selected':''}>${v}</option>`).join('')}</select></div>`).join('')}<div class="settings-row"><div><label>Graphics</label><small>3D courtyards or a lighter 2D map. Reopen Explore after changing.</small></div>${select('graphics',[['3d','3D mall · recommended'],['2d','2D map · lighter graphics']])}</div><div class="settings-row"><div><label>Game clock</label><small>Browsing and walking use this pace. Menus pause time.</small></div>${select('clockSeconds',[[1,'Normal · 1 sec / minute'],[2,'Cozy · 2 sec / minute'],[3,'Leisurely · 3 sec / minute']])}</div><div class="settings-row"><label>Walking speed</label>${select('walkSpeed',[[.75,'Unhurried'],[1,'Everyday'],[1.35,'Brisk']])}</div><div class="settings-row"><label>Animation</label>${select('motion',[['system','Follow device preference'],['full','Full animation'],['reduced','Reduced motion']])}</div>${[['crowds','Other shoppers','Bring the promenades to life.'],['sound','Gentle sound effects','Optional chimes for purchases and rewards.'],['largeText','Larger text','More room for reading and touch.']].map(([key,label,detail])=>`<div class="settings-row"><div><label for="pref-${key}">${label}</label><small>${detail}</small></div><input type="checkbox" id="pref-${key}" data-pref="${key}" ${s.preferences[key]?'checked':''}></div>`).join('')}<div class="settings-row"><div><label>Pause live clock</label><small>Shopping actions still use their stated time.</small></div><button class="toggle ${s.paused?'on':''}" data-action="settings-pause">${s.paused?'Paused':'Running'}</button></div><div class="service-links"><button class="button secondary" data-action="fullscreen">⛶ Toggle fullscreen / expanded play</button><button class="button secondary" data-action="save-tools">Save & recovery</button><button class="button secondary" data-action="export-save">Download this save</button><button class="button secondary" data-action="import-save">Import a save backup</button><button class="text-button" data-action="restart-confirm">Restart this ${s.sandbox?'free shop':'career'}</button></div><button class="button orange wide" data-action="close">Save & return ${icon('check')}</button></div>`,{small:true});}
function renderJournal(){const event=E.calendarToday(s),active=E.ERRANDS.find(e=>e.id===s.activeErrand?.id),candidates=E.errandCandidates(s),offers=E.errandOffers(s),spent=E.spentToday(s);$('#view-root').innerHTML=`<div class="page-title"><div><div class="eyebrow">DAY ${s.day} · ${E.dayName(s)}</div><h2>Your day, thoughtfully planned.</h2><p>Daily outings, shopping requests and little detours. The clock pauses while you plan.</p></div><button class="button secondary" data-action="view" data-id="mall">Back to the center ${icon('map')}</button></div>${communityBoard(s,{E,picture,esc:escapeHTML})}${companionBoard(s,{E,esc:escapeHTML})}${outingBoard(s,{E,picture,esc:escapeHTML})}<div class="journal-grid"><section class="journal-panel request-board"><div class="eyebrow">THE COMMUNITY REQUEST BOARD</div><h3>A favor for a friend.</h3><p>Accept a brief, inspect a matching real product, then buy it in your usual size. Deliver it unused. The client reimburses the full paid total plus your fee. A new purchase after acceptance is required.</p>${active?`<div class="active-request"><strong>${active.npc} · ${active.name}</strong><p>${active.text}</p><b>Budget including tax: ${E.money(active.budget)}</b><small>Fee ${E.money(active.fee)} + ${active.xp} XP · due tonight</small>${candidates.length?candidates.map(i=>`<button class="button orange wide" data-action="deliver-errand" data-id="${i.id}">Deliver ${E.byId(i.productId).name} · ${E.money(i.total+active.fee)}</button>`).join(''):`<p class="hint">No ready purchase yet. Buy a matching product after accepting, inspect its label, and keep its tags or packaging intact.</p>`}<button class="text-button" data-action="cancel-errand">Cancel this request</button></div><h4>Real models that fit the brief</h4><div class="request-shortlist">${E.PRODUCTS.filter(p=>E.levelOf(s)>=E.storeById(p.store).tier&&E.errandMatchesProduct(p,active)&&E.price(s,p)+Math.round(E.price(s,p)*E.TAX)<=active.budget).slice(0,8).map(p=>`<button data-action="errand-shop" data-id="${p.id}"><b>${escapeHTML(p.brand)} ${escapeHTML(p.name)}</b><span>${E.storeById(p.store).name} · ${E.money(E.price(s,p)+Math.round(E.price(s,p)*E.TAX))} incl. tax ↗</span></button>`).join('')}</div>`:offers.map(offer=>{const done=s.errands.some(e=>e.day===s.day&&e.id===offer.id);return `<article class="request-offer"><strong>${offer.name}</strong><small>${offer.npc} · ${E.money(offer.budget)} budget, including tax</small><p>${offer.text}</p><div><span>${E.money(offer.fee)} fee + reimbursement · ${offer.xp} XP</span><button class="button ${done?'secondary':'orange'} small" data-action="accept-errand" data-id="${offer.id}" ${done?'disabled':''}>${done?'Delivered ✓':'Accept brief'}</button></div></article>`;}).join('')}<p class="catalog-note">${s.errands.filter(e=>e.day===s.day).length}/3 requests completed today · ${s.metrics.errands} in your shopping life. Undelivered requests expire overnight.</p></section><div><section class="journal-panel"><div class="eyebrow">TODAY’S LITTLE OCCASION</div><h3>${event.name}</h3><p>${event.theme}</p><div class="hint">Enjoy ${E.ACTIVITIES.find(a=>a.id===event.activity).name} today to receive a one-time ${E.money(event.bonus)} game reward and ${event.xp} bonus XP.</div><button class="button orange wide" data-action="activity-visit" data-id="${event.activity}">${s.eventClaims.includes(s.day)?'Revisit the activity':'Visit today’s activity'} ${icon('arrow')}</button></section><section class="journal-panel budget-panel"><h3>A little spending plan.</h3><label for="daily-budget">Today’s checkout budget · game dollars</label><input id="daily-budget" type="number" min="0" max="1000000" step="1" value="${Math.round(s.dailyBudget/100)}"><div class="budget-total ${spent>s.dailyBudget?'over':''}"><span>Checkout total today, including tax</span><strong>${E.money(spent)} / ${E.money(s.dailyBudget)}</strong></div><p>This is a planning target. You choose whether to go beyond it. Client reimbursements and refunds do not change the checkout total. This target guides new outing offers; an accepted outing keeps its original allowance.</p><small>${E.carried(s).length}/8 purchases carried today · ${E.owned(s).filter(i=>i.checked).length} at guest services</small><button class="text-button" data-action="venue" data-id="services">Visit concierge & package check ↗</button></section></div></div><h3 class="section-title">A week at the Galleria</h3><div class="calendar-grid">${E.CALENDAR.map((day,i)=>`<article class="calendar-card ${(s.day-1)%7===i?'today':''}"><small>${['MON','TUE','WED','THU','FRI','SAT','SUN'][i]}</small><span>${E.ACTIVITIES.find(a=>a.id===day.activity).emoji}</span><h4>${day.name}</h4><p>${day.theme}</p><b>${E.money(day.bonus)} + ${day.xp} XP</b></article>`).join('')}</div><h3 class="section-title">There is more to a shopping day</h3><div class="activity-grid">${E.ACTIVITIES.map(a=>`<article class="journal-panel activity-card"><span>${a.emoji}</span><h3>${a.name}</h3><p>${a.description}</p><small>${a.minutes} minutes · ${a.price?E.money(a.price):'Free'} · +${a.recovery} stamina recovery</small><button class="button secondary" data-action="activity-visit" data-id="${a.id}">${s.activityLog.some(log=>log.day===s.day&&log.id===a.id)?'Visited today ✓':'Make a little detour'} ${icon('arrow')}</button></article>`).join('')}</div><section class="journal-panel"><h3>Little memories</h3><div class="memory-stats"><span>🤝 ${s.metrics.errands} favors completed</span><span>🎟 ${s.metrics.events} calendar events</span><span>🌿 ${s.metrics.activities} activities</span><span>📦 ${s.metrics.packages} packages checked</span><span>🌙 ${s.metrics.sleeps} mornings welcomed</span></div>${s.errands.length?`<div class="request-history">${s.errands.slice(-8).reverse().map(e=>`<p>Day ${e.day} · ${E.ERRANDS.find(b=>b.id===e.id)?.npc||'A friend'} · ${E.byId(e.product)?.name||'A thoughtful find'} · fee ${E.money(e.fee)}</p>`).join('')}</div>`:'<p>Your memories start with one small detour.</p>'}</section>`;}
function activityModal(id){const a=E.ACTIVITIES.find(a=>a.id===id);if(!a)return;const done=s.activityLog.some(log=>log.day===s.day&&log.id===id),event=E.calendarToday(s),bonus=event.activity===id&&!s.eventClaims.includes(s.day);modal(a.name,`${E.VENUES.find(v=>v.id===a.venue)?.name} · ${E.mallOf(s).name}`, `<div class="success-body"><div class="activity-illustration">${a.emoji}</div><h3>${a.name}</h3><p>${a.description}</p><div class="care-summary"><span>⏱ ${a.minutes} min</span><span>⚡ +${a.recovery} recovery</span><span>${a.price?E.money(a.price):'Free'}</span></div><p>Time passing still uses fullness. One visit per activity per game day earns a journal stamp and 15 XP.</p>${bonus?`<div class="hint">${event.name}: today’s visit also earns ${E.money(event.bonus)} and ${event.xp} bonus XP.</div>`:''}<button class="button orange wide" data-action="enjoy-activity" data-id="${a.id}" ${done?'disabled':''}>${done?'Today’s memory collected ✓':'Enjoy this activity'}</button><button class="button secondary wide" data-action="view" data-id="journal">Requests & weekly calendar</button></div>`,{small:true});}
function guestServices(){const checked=E.owned(s).filter(i=>i.checked);modal('A little help with your day.', E.mallOf(s).name+' · Guest services',`<div class="modal-body"><div class="hint">Your shopping bags have room for eight purchases. Leave today’s purchases here to free your hands; collect them before use, delivery, or returns. Any remaining packages go home automatically when you sleep.</div><div class="concierge-moments"><button class="button secondary" data-action="community-board">📌 Community notices · free · 3 min</button><button class="button secondary" data-action="lost-property">🔎 Lost-property desk · free · 6 min</button><button class="button secondary" data-action="guestbook-open">✍ Guestbook · free · 5 min</button><button class="button secondary" data-action="gift-wrapping">🎁 Gift wrapping · $2 · 6 min</button><button class="button secondary" data-action="water-station">💧 Water station · free · 3 min</button></div><div class="service-links"><button class="button orange" data-action="check-packages" ${E.carried(s).length?'':'disabled'}>Check ${E.carried(s).length} carried purchases · free · 5 min</button><button class="button secondary" data-action="view" data-id="journal">Requests, calendar & spending plan</button><button class="button secondary" data-action="catalog">Full directory & ${E.PRODUCTS.length} real products</button><button class="button secondary" data-action="view" data-id="receipts">Receipts & return deadlines</button></div>${checked.length?`<h3>Your checked packages</h3>${checked.map(i=>`<div class="package-row"><span>${E.byId(i.productId).name}</span><button class="button secondary small" data-action="collect-package" data-id="${i.id}">Collect · 3 min</button></div>`).join('')}`:'<p>No packages waiting at concierge.</p>'}${passportHTML()}</div>`,{small:true});}
function startNight(resuming=false){if(recovery||journeyBusy)return;mapPanel=null;renderMapPanel();journeyBusy=true;nightDay=s.day;s.nightPending=nightDay;save();if(recovery)return;closeModal();s.mapOverview=false;if(view!=='mall')showView('mall');else redrawMall();document.body.classList.add('journeying');$('#journey-root').innerHTML=`<div class="departure-bar" role="status"><span>Your shopper is walking to the home exit…</span><button class="button secondary small" data-action="skip-night">Skip animation & sleep</button></div>`;focusMap();setGameInert(true);$('#journey-root button').focus();world.beginExit(showHomeJourney);hud();}
function showHomeJourney(){if(recovery||!journeyBusy)return;world?.destroy();world=null;$('#journey-root').innerHTML=`<div class="journey-overlay"><section class="night-card" role="dialog" aria-modal="true" aria-label="Walking home and going to sleep"><header><div><small>DAY ${nightDay} · HOMEWARD BOUND</small><h2>A little walk. A well-earned rest.</h2></div><button class="button secondary small" data-action="skip-night">Skip animation & sleep</button></header><canvas class="night-scene" width="1600" height="896" aria-label="Animated shopper walking from the shopping center to home, then to bed."></canvas><p data-journey-caption aria-live="polite">Walking home through the evening lights…</p></section></div>`;$('#journey-root button').focus();homeJourney=new HomeJourney($('#journey-root'),s,finishNight);}
function finishNight(){if(recovery||!journeyBusy)return;journeyBusy=false;setGameInert(false);homeJourney?.destroy();homeJourney=null;world?.destroy();world=null;$('#journey-root').innerHTML='';document.body.classList.remove('journeying');const recap=E.completeNight(s,nightDay);cart={};store=null;pendingProduct=null;pendingReturn=null;lastClosingDay=0;save();if(recovery)return;showView('mall');if(!recap)return;chime();modal('A new little day.',`DAY ${s.day} · ${E.dayName(s)} · Breakfast is ready`, `<div class="success-body"><div class="success-icon">🌤</div><h3>Good morning, ${escapeHTML(s.playerName)}.</h3><p>Home, a full night’s sleep, and a new day ahead.<br>Your purchases and checked packages are safely home.</p><div class="recap-grid"><div class="recap-cell"><small>Work-shift income</small><strong>${E.money(recap.pay)}</strong></div><div class="recap-cell"><small>Yesterday’s goals</small><strong>${recap.goals} / ${E.QUESTS.length}</strong></div><div class="recap-cell"><small>Stamina & fullness</small><strong>100 / 100</strong></div><div class="recap-cell"><small>Today’s occasion</small><strong>${E.calendarToday(s).name}</strong></div></div>${recap.outing?`<div class="outing-recap"><strong>Yesterday’s outing · ${escapeHTML(recap.outing.title)}</strong>${recap.outing.claimed?"Completed and reward collected ✓":recap.outing.complete+" / "+recap.outing.total+" steps · choose a fresh outing today"}</div>`:""}<p>Fresh stock, new daily outings, community requests and a rotating pavilion showcase await.</p><button class="button orange" data-action="close">Step into the new day ${icon('arrow')}</button><button class="button secondary" data-action="view" data-id="journal">Plan today’s little adventures</button><button class="text-button" data-action="main-menu">Main menu</button></div>`,{small:true});}
function exportSave(){downloadRaw(JSON.stringify(s,null,2),`mallside-${mode}-day-${s.day}.json`);}
function importSave(){pendingImport=null;modal('Bring your shopping life with you.', 'Paste the contents of an exported Mallside JSON save.',`<div class="modal-body"><label for="save-import">Save backup JSON</label><textarea id="save-import" rows="10" spellcheck="false" placeholder="Paste your Mallside save here"></textarea><p>The backup’s career or free-shop mode is only replaced after review. Your other mode is preserved.</p><button class="button orange wide" data-action="review-import">Review this backup</button></div>`,{small:true});}
function reviewImport(){try{const state=E.validateImport($('#save-import').value),target=state.sandbox?'free':'career';pendingImport={mode:target,state,expected:saves.inspect(target)};modal('Restore this shopping life?', 'Review the backup before replacing this mode.',`<div class="success-body">${saveSummary(state,E.money)}<p>${modeLabel(target)} save · your other mode is preserved. Recent actions in this mode may be rolled back.</p><button class="button orange" data-action="apply-import">Restore reviewed backup</button><button class="button secondary" data-action="close">Keep stored progress</button></div>`,{small:true});}catch(error){toast(error.message,true);}}

function research(){modal('A real-world spark. An original little world.', 'Design notes & official sources',`<div class="modal-body"><p>Mallside now has ten original destination layouts; see the <a href="#" data-action="view" data-id="malls">destination passport</a> for each real center and its official source. Our garden and luxury scenes take inspiration from the gardens, bridge, glass-roof courts, carousel, dining, and concierge services of <a href="https://www.southcoastplaza.com/concierge/" target="_blank" rel="noopener noreferrer">South Coast Plaza</a>. Our layout, people, events, art, economy, and store placements are original game design.</p><p>The daily rhythm draws on <a href="https://www.stardewvalley.net/about/" target="_blank" rel="noopener noreferrer">Stardew Valley</a>; thoughtful customer briefs and personal expression are informed by <a href="https://www.nintendo.com/au/games/nintendo-3ds/new-style-boutique-3-styling-star/" target="_blank" rel="noopener noreferrer">Styling Star</a> and <a href="https://fashion-dreamer.com/" target="_blank" rel="noopener noreferrer">Fashion Dreamer</a>.</p><p>Friendship stories, saved looks, collection shelves, daily styling briefs and playable workshops give each trip a lasting result. The next-step guide follows the objective-clarity principles in <a href="https://learn.microsoft.com/en-us/xbox/accessibility/xbox-accessibility-guidelines/109" target="_blank" rel="noopener noreferrer">Microsoft’s game accessibility guidance</a>. All activities and social systems run offline.</p><p>All 548 shop listings include photographs of real named merchandise and product reference links. Some photographs use documented retailer or archive sources. Pictured colors can differ from illustrated avatar equipment. Some refer to archive or earlier-generation models. Prices, availability, sizing feedback, return policies, services, and rewards are simulated. Budget stores in this game are not presented as South Coast Plaza tenants.</p><button class="button secondary wide" data-action="sources">Browse official product sources</button><p>Independent fan-made game. No affiliation, real purchases, or real payments. Saves remain in this browser unless you export a backup.</p></div>`,{small:true});}

