 'studio-pose':button=>{previewPose=button.dataset.id;preview3D?.setPose(previewPose);$$('[data-action="studio-pose"]').forEach(b=>{b.classList.toggle('active',b===button);if(b.hasAttribute('aria-pressed'))b.setAttribute('aria-pressed',String(b===button));});},
 'studio-camera':button=>{previewFocus=button.dataset.id;preview3D?.setFocus(previewFocus);$$('[data-action="studio-camera"]').forEach(b=>{b.classList.toggle('active',b===button);if(b.hasAttribute('aria-pressed'))b.setAttribute('aria-pressed',String(b===button));});},
 'claim-destination':button=>{const r=perform(()=>E.claimDestination(s,button.dataset.id));if(r.ok)toast('Destination stamp collected · +'+r.value.xp+' XP.');},
