 'skip-activity':()=>activityScene?.finish(),
 'food':()=>goVenue('food'),'coffee':()=>goVenue('coffee'),'rest':()=>goVenue('rest'),'end-day':()=>endDay(),
 'coffee-order':button=>{const r=perform(()=>E.eat(s,button.dataset.id));if(r.ok){playActivity('drink',r.value.name,coffeeShop);}},
